INSERT INTO jeongmo_required_members (jeongmo_id, member_id)
SELECT #{jeongmoId}, #{memberId}
WHERE NOT EXISTS (
    SELECT 1
    FROM jeongmo_required_members
    WHERE jeongmo_id = #{jeongmoId}
      AND member_id = #{memberId}
)

